from pathlib import Path

ROOT = Path(__file__).parent
T = ROOT / "frontend" / "templates"
P = T / "partials"
CSS = ROOT / "frontend" / "static" / "css"
JS = ROOT / "frontend" / "static" / "js"

for d in [P, CSS / "pages", JS / "core", JS / "components", JS / "pages"]:
    d.mkdir(parents=True, exist_ok=True)

def w(path: Path, text: str):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text.strip() + "\n", encoding="utf-8")

base = r'''<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover">
  <meta name="theme-color" content="#7c3aed">
  <title>{% block title %}SocialHub{% endblock %}</title>
  <script>(function(){try{var p=localStorage.getItem('socialhub-theme')||'system';var m=matchMedia('(prefers-color-scheme: dark)');document.documentElement.dataset.theme=p==='system'?(m.matches?'dark':'light'):p;document.documentElement.dataset.themePreference=p}catch(e){document.documentElement.dataset.theme='dark'}})();</script>
  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css">
  <link rel="stylesheet" href="/static/css/style.css">
  {% block styles %}{% endblock %}
</head>
<body data-page="{% block page_name %}{{ request.url.path.strip('/').replace('/', '-') or 'home' }}{% endblock %}" class="{% block body_class %}{% endblock %}">
{% block body %}
<a class="skip-link" href="#main-content">Skip to content</a>
<div class="app-shell">
  {% include 'partials/desktop_sidebar.html' %}
  <div class="app-main">
    {% include 'partials/topbar.html' %}
    <main id="main-content" class="page-container" tabindex="-1">{% block content %}{% endblock %}</main>
  </div>
  {% include 'partials/right_sidebar.html' %}
  {% include 'partials/mobile_bottom_nav.html' %}
</div>
{% include 'partials/user_menu.html' %}
{% include 'partials/notification_menu.html' %}
{% include 'partials/create_post_modal.html' %}
{% include 'partials/create_reel_modal.html' %}
{% include 'partials/create_story_modal.html' %}
{% include 'partials/share_modal.html' %}
{% include 'partials/comments_drawer.html' %}
{% include 'partials/confirmation_modal.html' %}
{% include 'partials/loading_overlay.html' %}
{% include 'partials/toast_container.html' %}
{% endblock %}
<script type="module" src="/static/js/app.js"></script>
{% block scripts %}{% endblock %}
</body>
</html>'''
w(T / "base.html", base)

