w(CSS / "style.css", style)
for name in ["tokens","reset","base","layout","components","forms","modals","responsive","themes"]:
    w(CSS / f"{name}.css", f"/* SocialHub {name}: canonical rules are imported into style.css for no-build delivery. */")
for name in ["auth","home","profile","reels","stories","chat","search","notifications","settings","creator","instagram-studio","data-studio","marketplace","live","wallet","admin"]:
    w(CSS / "pages" / f"{name}.css", f"/* Page-specific hook file for {name}. Shared design system lives in style.css. */")

def page(name, page_name, title, content):
    w(T / name, "{% extends 'base.html' %}\n{% block title %}" + title + "{% endblock %}\n{% block page_name %}" + page_name + "{% endblock %}\n{% block content %}\n" + content.strip() + "\n{% endblock %}")

